Q: Animating scroll on ScrollView programmatically? A: <p>The interactive scroll works if you start it from somewhere else (f.e. <code>Button</code> action) but not from the <code>onAppear</code> modifier. I'd guess this is intentional behavior to prevent the user seeing the scrolling when the view appears (or a bug in SwiftUI...). An ugly workaround is to defer the animation with an <code>DispatchQueue.main.async</code>:</p>
<pre class="lang-swift prettyprint-override"><code>import SwiftUI

struct ContentView: View {
    let words = [&quot;planet&quot;, &quot;kidnap&quot;, &quot;harbor&quot;, &quot;legislation&quot;, &quot;soap&quot;, &quot;management&quot;, &quot;prejudice&quot;, &quot;an&quot;, &quot;trunk&quot;, &quot;divide&quot;, &quot;critic&quot;, &quot;area&quot;, &quot;affair&quot;]

    @State var selectedWord: String?

    var body: some View {
        ScrollViewReader { proxy in
            VStack(alignment: .leading) {
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 10) {
                        ForEach(words, id: \.self) { word in
                            Text(word)
                                .background(self.selectedWord == word ? Color.yellow : nil)
                                .id(word)
                        }
                    }
                }

                Button(&quot;Scroll to random word&quot;) {
                    withAnimation(Animation.easeInOut(duration: 1)) {
                        let word = words.randomElement()
                        self.selectedWord = word
                        proxy.scrollTo(word)
                    }
                }
            }
            .onAppear {
                DispatchQueue.main.async {   // &lt;--- workaround
                    withAnimation(Animation.easeInOut(duration: 1).delay(1)) {
                        let word = self.words.last
                        self.selectedWord = word
                        proxy.scrollTo(word)
                    }
                }
            }
        }
        .padding(10)
    }
}
</code></pre>

Q: three.js OBJLoader.js error on initialization A: <p>I changed the code so it uses an import map, like the examples provided, and this fixed the issue. There must be a version mismatch between the tutorial and what I'm using.</p>
<p>HTML file</p>
<pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;en&quot;&gt;
    &lt;head&gt;

        &lt;meta http-equiv=&quot;content-type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;

        &lt;title&gt;Three.js Learning Environment&lt;/title&gt;

        &lt;meta name=&quot;title&quot;       content=&quot;Three.js Learning Environment&quot; /&gt;
        &lt;meta name=&quot;googlebot&quot;   content=&quot;noindex&quot; /&gt;
        &lt;meta name=&quot;robots&quot;      content=&quot;noindex&quot; /&gt;

        &lt;meta http-equiv=&quot;cache-control&quot; content=&quot;no-cache&quot; /&gt;
        &lt;meta http-equiv=&quot;pragma&quot;        content=&quot;no-cache&quot; /&gt;

        &lt;script type=&quot;importmap&quot;&gt;
        {
            &quot;imports&quot;: {
                &quot;three&quot;: &quot;./three.js/build/three.module.js&quot;,
                &quot;three/addons/&quot;: &quot;./three.js/examples/jsm/&quot;
            }
        }
    &lt;/script&gt;

        &lt;style&gt;
            #test-env {
                border:  1px solid #666; 
                margin:  auto; 
                padding: 0px;
            }
        &lt;/style&gt;

    &lt;/head&gt;
    &lt;body&gt;

        &lt;script type=&quot;module&quot; src=&quot;three-js-test.js&quot;&gt;&lt;/script&gt;

    &lt;/body&gt;
&lt;/html&gt;
</code></pre>
<p>.JS file</p>
<pre><code>
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { OBJLoader } from 'three/addons/loaders/OBJLoader.js';

const scene    = new THREE.Scene();
const camera   = new THREE.PerspectiveCamera(75, (window.innerWidth/window.innerHeight), 0.1, 1000);
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const light = new THREE.AmbientLight(0xffffff, 1);
scene.add(light);

const loader = new OBJLoader();
loader.load(
    'https://10.1.10.101/work-shop/base_assets/obj/Human/Characters/footman.obj',
    function( object ) {
        scene.add(object);
    },
    function( xhr ) {
        console.log((xhr.loaded/xhr.total*100)+&quot;% loaded.&quot;);
    },
    function( error ) {
        console.error(&quot;An error happened&quot;, error);
    }
);

function animate() {
    requestAnimationFrame(animate);
    renderer.render(scene, camera);
};
</code></pre>

Q: Material UI Select - Change Select size A: <p>Indeed the <code>size=&quot;small&quot;</code> setting on <code>&lt;FormControl&gt;</code> doesn't make the whole <code>Select</code> block very small, or small enough for my needs.</p>
<p>Setting <code>fontSize</code> using the <a href="https://mui.com/system/getting-started/the-sx-prop/" rel="nofollow noreferrer">sx prop</a> reduces the size respecting the paddings ratio:</p>
<pre><code>&lt;Select
  labelId=&quot;simple-select-label&quot;
  id=&quot;simple-select&quot;
  value={ value }
  onChange={(e) =&gt; this.handleChange(e)}
  label=&quot;Size&quot;
  sx={{
    fontSize: &quot;.75rem&quot;
  }}
&gt;
</code></pre>
<p>In order to have the <code>&lt;MenuItem&gt;</code> options styled, att the same setting to them:</p>
<pre><code>&lt;Select
  labelId=&quot;simple-select-label&quot;
  id=&quot;simple-select&quot;
  value={ value }
  onChange={(e) =&gt; this.handleChange(e)}
  label=&quot;Size&quot;
  sx={{
    fontSize: &quot;.75rem&quot;
  }}
&gt;
  &lt;MenuItem sx={{ fontSize: &quot;.75rem&quot; }}&gt;Acrylic&lt;/MenuItem&gt;
  &lt;MenuItem sx={{ fontSize: &quot;.75rem&quot; }}&gt;Policarbonate&lt;/MenuItem&gt;
&lt;/Select&gt;
</code></pre>
